func TestAggregateKeepsAgentIdentity(t *testing.T) {
	a := twoAgents()
	a.addLine(1, "agent-a1.jsonl", 0, msgLine("m", "x", "end_turn", 1, 1, 0, 0))
	got := a.finish()[1]
	if got.ID != "a1" || got.Type != "coder" || got.SpawnDepth != 1 || got.State != StateFinished || got.Main {
