	a.addLine(0, "p.jsonl", 0, msgLine("a", "x", "end_turn", maxI, 0, 0, 0))
	a.addLine(0, "p.jsonl", 10, msgLine("b", "x", "end_turn", maxI, 0, 0, 0))
